const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Swannanoa River location (near Asheville, NC)
  const riverPoint = ee.Geometry.Point([-82.5273, 35.5951]);
  const riverBuffer = riverPoint.buffer(100); // 100m buffer for river sampling

  // Date ranges with small buffer
  const date1Start = '2024-08-28';
  const date1End = '2024-09-01';
  const date2Start = '2024-09-30';
  const date2End = '2024-10-04';

  // Load Sentinel-2 Surface Reflectance
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(riverPoint)
    .filterDate(date1Start, date1End)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(riverPoint)
    .filterDate(date2Start, date2End)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Aug 30 images: ${size1}, Oct 2 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Insufficient images for comparison.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get best images (least cloudy over AOI)
  const img1 = col1.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const img2 = col2.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // Calculate brownness index (Red/Blue ratio)
  // Higher ratio = browner water
  const brownness1 = img1.select('B4').divide(img1.select('B2')).rename('brownness');
  const brownness2 = img2.select('B4').divide(img2.select('B2')).rename('brownness');

  // Calculate statistics over river area
  const stats1 = await brownness1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: riverBuffer,
    scale: 10,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await brownness2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: riverBuffer,
    scale: 10,
    maxPixels: 1e9
  }).getInfo();

  const brown1 = stats1.brownness_mean;
  const count1 = stats1.brownness_count;
  const brown2 = stats2.brownness_mean;
  const count2 = stats2.brownness_count;

  console.log(`Aug 30: Brownness=${brown1?.toFixed(3)}, Pixels=${count1}`);
  console.log(`Oct 2: Brownness=${brown2?.toFixed(3)}, Pixels=${count2}`);

  if (!count1 || count1 === 0 || !count2 || count2 === 0) {
    console.log("No valid pixels over river area.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (brown1 == null || brown2 == null || isNaN(brown1) || isNaN(brown2)) {
    console.log("Calculation failed - invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if October image is significantly browner
  const increase = ((brown2 - brown1) / brown1) * 100;
  console.log(`Brownness increase: ${increase.toFixed(1)}%`);

  if (brown2 > brown1 * 1.15) {
    console.log("Oct 2 was visibly browner (>15% increase).");
    console.log("<answer>A</answer>");
  } else {
    console.log("No significant brownness increase detected.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
